import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 numel
)
{
    .reg .pred %p<2>;
    .reg .b32 %r<6>;
    .reg .b64 %rd<7>;
    .reg .f32 %f<16>;

    // Load parameters
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r2, [numel];

    // Compute linear thread index
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mad.lo.s32 %r4, %r1, %r3, %r0;

    // Bounds check
    setp.ge.u32 %p1, %r4, %r2;
    @%p1 bra DONE;

    // Byte offset and pointers
    mul.wide.u32 %rd3, %r4, 4;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;

    // Load x
    ld.global.f32 %f0, [%rd4];

    // Compute GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
    // x^2 and x^3
    mul.rn.f32 %f1, %f0, %f0;        // x^2
    mul.rn.f32 %f2, %f1, %f0;        // x^3

    // u = x + 0.044715 * x^3
    mov.f32 %f3, 0.044715;
    fma.rn.f32 %f4, %f2, %f3, %f0;   // f4 = x + 0.044715*x^3

    // v = sqrt(2/pi) * u
    mov.f32 %f5, 0.7978845834732056; // sqrt(2/pi)
    mul.rn.f32 %f6, %f4, %f5;

    // w = tanh(v)
    tanh.approx.f32 %f7, %f6;

    // y = 0.5 * x * (1 + w)
    mov.f32 %f8, 1.0;
    add.rn.f32 %f9, %f8, %f7;        // 1 + w
    mov.f32 %f10, 0.5;
    mul.rn.f32 %f11, %f10, %f0;      // 0.5 * x
    mul.rn.f32 %f12, %f11, %f9;      // result

    // Store result
    st.global.f32 [%rd5], %f12;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor.")
        if x.dtype != torch.float32:
            raise RuntimeError("Input must be float32.")
        if not x.is_contiguous():
            raise RuntimeError("Input must be contiguous.")

        out = torch.empty(x.shape, device=x.device, dtype=x.dtype)
        N = x.numel()

        block_x = 256
        grid_x = (N + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

